s=s[:a]+'''const formatters = new Map<string, Intl.DateTimeFormat>();

/** Throws a `RangeError` for a zone name `Intl` does not recognise. */
export function assertValidTimeZone(timeZone: string): void {
  formatterFor(timeZone);
}

function formatterFor(timeZone: string): Intl.DateTimeFormat {
  let formatter = formatters.get(timeZone);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "numeric",
      day: "numeric",
      hour: "numeric",
      minute: "numeric",
      second: "numeric",
    });
    formatters.set(timeZone, formatter);
  }
  return formatter;
}

interface WallClock {
  readonly year: number;
  readonly month: number;
  readonly day: number;
  readonly hour: number;
}

function wallClock(ms: number, timeZone: string): WallClock {
  const parts: Record<string, number> = {};
  for (const part of formatterFor(timeZone).formatToParts(new Date(ms))) {
    if (part.type !== "literal") parts[part.type] = Number(part.value);
  }
  return {
    year: parts.year ?? 0,
    month: parts.month ?? 1,
    day: parts.day ?? 1,
    hour: (parts.hour ?? 0) % 24,
  };
}

/** Milliseconds the zone's wall clock is ahead of UTC at the given instant. */
function offsetAt(ms: number, timeZone: string): number {
  const parts: Record<string, number> = {};
  for (const part of formatterFor(timeZone).formatToParts(new Date(ms))) {
    if (part.type !== "literal") parts[part.type] = Number(part.value);
  }
  const wall = Date.UTC(
    parts.year ?? 0,
    (parts.month ?? 1) - 1,
    parts.day ?? 1,
    (parts.hour ?? 0) % 24,
    parts.minute ?? 0,
    parts.second ?? 0,
  );
  return wall - Math.floor(ms / 1000) * 1000;
}

/**
 * Every instant (ascending) at which the zone's wall clock reads
 * `year-month-day hour:00`. Two instants when a DST fall-back repeats the
 * hour; when a spring-forward skips it, the single instant at which the clock
 * jumped past it.
 */
function instantsAtWall(
  year: number,
  month: number,
  day: number,
  hour: number,
  timeZone: string,
): number[] {
  const wall = Date.UTC(year, month - 1, day, hour, 0, 0, 0);
  const before = offsetAt(wall - DAY_MS, timeZone);
  const after = offsetAt(wall + DAY_MS, timeZone);

  const found = new Set<number>();
  for (const offset of new Set([before, after])) {
    const candidate = wall - offset;
    if (offsetAt(candidate, timeZone) === offset) found.add(candidate);
  }
  if (found.size === 0) found.add(wall - before);
  return [...found].sort((a, b) => a - b);
}

function shiftCalendarDay(
  year: number,
  month: number,
  day: number,
  days: number,
): { year: number; month: number; day: number } {
  const shifted = new Date(Date.UTC(year, month - 1, day + days));
  return {
    year: shifted.getUTCFullYear(),
    month: shifted.getUTCMonth() + 1,
    day: shifted.getUTCDate(),
  };
}

function pad(value: number, width: number): string {
  return String(value).padStart(width, "0");
}

/** The `YYYY-MM-DD` calendar date of an instant on the zone's clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const { year, month, day } = wallClock(parseIso(value).getTime(), timeZone);
  return `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}`;
}

/** The hour (0-23) the zone's clock shows at `reference`. */
export function localHour(reference: Date, timeZone: string): number {
  return wallClock(reference.getTime(), timeZone).hour;
}

/** The instant a `YYYY-MM-DD` calendar day began on the zone's clock. */
export function startOfLocalDate(date: string, timeZone: string): IsoTimestamp {
  const [year = 0, month = 1, day = 1] = date.split("-").map(Number);
  const [first = NaN] = instantsAtWall(year, month, day, 0, timeZone);
  return toIsoTimestamp(new Date(first));
}

/** The date `days` calendar days from a `YYYY-MM-DD` date (may be negative). */
